syntax:
struct Base {
    void (*destroy)(struct Base *);
    // other common members
};

struct Derived {
    struct Base base;
    // additional members
};

// Function implementations
void base_destroy(struct Base *b) { /* ... */ }
void derived_destroy(struct Base *b) {
    // cast to Derived if needed
    // perform derived-specific cleanup
}

// Usage
struct Derived d;
d.base.destroy = derived_destroy;
// Call destructor polymorphically
b->destroy(b);

code_example:
struct Query_base {
    void (*destroy)(struct Query_base *);
};

struct AndQuery {
    struct Query_base base;
    // additional members for AndQuery
};

struct OrQuery {
    struct Query_base base;
    // additional members for OrQuery
};

void destroy_query(struct Query_base *q) {
    q->destroy(q);
}

// Derived class-specific destroy functions
void destroy_and_query(struct Query_base *q) {
    struct AndQuery *aq = (struct AndQuery *)q;
    // cleanup for AndQuery
}
void destroy_or_query(struct Query_base *q) {
    struct OrQuery *oq = (struct OrQuery *)q;
    // cleanup for OrQuery
}

// Assigning function pointers
struct AndQuery and_q;
and_q.base.destroy = destroy_and_query;

struct OrQuery or_q;
or_q.base.destroy = destroy_or_query;

// Usage example
destroy_query((struct Query_base *)&and_q);
destroy_query((struct Query_base *)&or_q);
